-- 可配置权限体系：预置数据（20260807）
-- 由 scripts/rbac/generate-seed-migration.ts 生成，不要手改。
-- 幂等：可重复执行。

-- 1. 权限点目录（lib/rbac/catalog.ts 的镜像）

-- 2. 12 个预置角色。isSystem=true → 配置页里不可删除，但权限可改。
--    这里用 DO NOTHING 而不是 DO UPDATE：管理员在页面上调过的权限不该被下次部署冲掉。

-- 3. 把现有用户挂到对应的预置角色上。
--    口径与 lib/auth.ts 的 effectiveRoles 一致：roles[] 非空时用它，否则回退单 role。
--    ⛔ 这一步不做的话，平迁后所有人权限集为空，等于全员被锁在门外。
SELECT u."id", r."id"
FROM "User" u
JOIN LATERAL (
  SELECT CASE WHEN cardinality(u."roles") > 0 THEN u."roles"
              ELSE ARRAY[u."role"::TEXT] END AS effective
) e ON TRUE
JOIN LATERAL unnest(e.effective) AS role_name ON TRUE
JOIN "AppRole" r ON r."code" = lower(role_name)
ON CONFLICT ("userId","roleId") DO NOTHING;

